// Renders the work log from work/index.json (generated by scripts/build_index.py).
(function () {
  "use strict";

  function el(tag, attrs, children) {
    var node = document.createElement(tag);
    Object.keys(attrs || {}).forEach(function (k) {
      if (k === "text") node.textContent = attrs[k];
      else node.setAttribute(k, attrs[k]);
    });
    (children || []).forEach(function (c) { node.appendChild(c); });
    return node;
  }

  function fmtDate(iso) {
    var d = new Date(iso + "T00:00:00");
    return isNaN(d) ? iso : d.toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" });
  }

  function card(entry) {
    var head = el("div", {}, [
      el("h3", { text: entry.title }),
      el("p", { class: "meta", text: fmtDate(entry.date) + (entry.status ? " · " + entry.status : "") })
    ]);
    var tags = el("div", { class: "tags" }, (entry.tags || []).map(function (t) {
      return el("span", { class: "tag", text: t });
    }));
    return el("a", { class: "card", href: "work.html#" + encodeURIComponent(entry.slug) },
      [head, el("p", { text: entry.summary }), tags]);
  }

  function renderCards(container, entries) {
    container.replaceChildren();
    if (!entries.length) {
      container.appendChild(el("p", { class: "empty", text: "No entries yet." }));
      return;
    }
    entries.forEach(function (e) { container.appendChild(card(e)); });
  }

  function renderEntry(container, entry) {
    container.replaceChildren(
      el("a", { class: "back", href: "work.html", text: "← All entries" }),
      el("h1", { text: entry.title }),
      el("p", { class: "meta", text: fmtDate(entry.date) + (entry.status ? " · " + entry.status : "") })
    );
    if (entry.tags && entry.tags.length) {
      container.appendChild(el("div", { class: "tags", style: "margin-top:0.5rem" }, entry.tags.map(function (t) {
        return el("span", { class: "tag", text: t });
      })));
    }
    if (entry.links && entry.links.length) {
      container.appendChild(el("div", { class: "links" }, entry.links.map(function (l) {
        return el("a", { class: "btn", href: l.url, target: "_blank", rel: "noopener", text: l.label });
      })));
    }
    var body = el("div", { class: "prose" });
    body.innerHTML = marked.parse(entry.body || "");
    container.appendChild(body);
    document.title = entry.title + " | Yashowardhan Rai";
  }

  function load() {
    return fetch("work/index.json", { cache: "no-cache" })
      .then(function (r) { if (!r.ok) throw new Error(r.status); return r.json(); })
      .catch(function () { return []; });
  }

  load().then(function (entries) {
    // Home page: latest three.
    var latest = document.getElementById("latest-work");
    if (latest) renderCards(latest, entries.slice(0, 3));

    // Work log page: list + entry view, switched by URL hash.
    var list = document.getElementById("work-list");
    var view = document.getElementById("work-entry");
    if (!list || !view) return;

    var all = document.getElementById("all-work");
    var filters = document.getElementById("filters");
    var active = null;

    var tags = [];
    entries.forEach(function (e) {
      (e.tags || []).forEach(function (t) { if (tags.indexOf(t) < 0) tags.push(t); });
    });
    tags.sort();
    tags.forEach(function (t) {
      var b = el("button", { class: "tag", type: "button", "aria-pressed": "false", text: t });
      b.addEventListener("click", function () {
        active = active === t ? null : t;
        Array.prototype.forEach.call(filters.children, function (c) {
          c.setAttribute("aria-pressed", String(c.textContent === active));
        });
        renderCards(all, active ? entries.filter(function (e) { return (e.tags || []).indexOf(active) >= 0; }) : entries);
      });
      filters.appendChild(b);
    });

    function route() {
      var slug = decodeURIComponent(location.hash.slice(1));
      var entry = entries.filter(function (e) { return e.slug === slug; })[0];
      if (entry) {
        list.hidden = true; view.hidden = false;
        renderEntry(view, entry);
        window.scrollTo(0, 0);
      } else {
        view.hidden = true; list.hidden = false;
        document.title = "Work log | Yashowardhan Rai";
        renderCards(all, active ? entries.filter(function (e) { return (e.tags || []).indexOf(active) >= 0; }) : entries);
      }
    }
    window.addEventListener("hashchange", route);
    route();
  });
})();
